import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
A=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
px={}
for a in A:
    d=get_stock_daily_data(a,days=1800)
    if d is not None and len(d)>100: px[a]=d.set_index('date').close.astype(float)
p=pd.concat(px,axis=1).sort_index().ffill(); r=p.pct_change(); market=r.mean(axis=1)
# Residualized 5-day reversal: remove contemporaneous cross-asset market component from trailing return.
trail=p.pct_change(5); f=pd.DataFrame(index=p.index,columns=p.columns,dtype=float)
for i in range(len(p)):
    if i<60: continue
    q=pd.concat([r.iloc[max(0,i-60):i].mean(axis=1).rename('m'), r.iloc[max(0,i-60):i].mean(axis=1)],axis=1)
    # trailing five day return and market five-day return, beta estimated from prior daily returns
    mr=market.iloc[max(0,i-60):i]
    var=float(mr.var())
    for a in p.columns:
        ar=r[a].iloc[max(0,i-60):i]
        beta=float(ar.cov(mr)/var) if var>1e-14 else 0.
        f.loc[p.index[i],a]=-(trail.loc[p.index[i],a]-beta*market.iloc[max(0,i-5):i].sum())
obs=[]; turns=[]; cov=[]
for i in range(len(p)-1):
    q=pd.concat([f.iloc[i].rename('f'),r.iloc[i+1].rename('y')],axis=1).dropna()
    if len(q)>=8: obs.append(q.f.corr(q.y)); cov.append(len(q)/15)
    if i:
        q2=pd.concat([f.iloc[i],f.iloc[i-1]],axis=1).dropna()
        if len(q2)>=8: turns.append((q2.iloc[:,0].rank()!=q2.iloc[:,1].rank()).mean())
x=np.array(obs); print('assets',len(px),'dates',len(x),'instruments',len(px),'range',p.index.min(),p.index.max())
print('meanIC',np.nanmean(x),'ICIR',np.nanmean(x)/np.nanstd(x,ddof=1),'hit',np.mean(x>0),'coverage',np.mean(cov),'turn',np.mean(turns))
for h in [5,10]:
 oo=[]
 for i in range(len(p)-h):
  q=pd.concat([f.iloc[i].rename('f'),p.pct_change(h).iloc[i+h].rename('y')],axis=1).dropna()
  if len(q)>=8: oo.append(q.f.corr(q.y))
 print('decay',h,np.nanmean(oo),len(oo))
# regime split by market trailing 20d sign
for label,mask in [('up',market.rolling(20).mean()>0),('down',market.rolling(20).mean()<0)]:
 z=[]
 for i in range(len(p)-1):
  if bool(mask.iloc[i]):
   q=pd.concat([f.iloc[i].rename('f'),r.iloc[i+1].rename('y')],axis=1).dropna()
   if len(q)>=8:z.append(q.f.corr(q.y))
 print(label,'dates',len(z),'IC',np.nanmean(z))

